import re


_JOB_PATTERN = re.compile(
    r"""^JOB\s+
        (?P<name>\S+)\s+AT\s+
        (?P<at>\d{2}:\d{2})\s+RUN\s+
        (?P<script>\S+)
        (?:\s+ON_ERROR\s+(?P<on_error>ABORT|CONTINUE|RETRY:\d+))?
        \s*$""",
    re.VERBOSE,
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse Meridian CRM batch job configuration text."""
    schedule = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid job configuration on line {line_number}")

        clause = match.group("on_error") or "ABORT"
        if clause == "ABORT":
            policy = "ABORT"
            retries = 0
        elif clause == "CONTINUE":
            policy = "CONTINUE"
            retries = 0
        else:
            policy = "RETRY"
            retries = int(clause.removeprefix("RETRY:"))

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": {"policy": policy, "retries": retries},
            }
        )

    return schedule
